import{_ as a,o,c as t,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Visits and shops","description":"","frontmatter":{"pageId":"players/visits","contentRevision":2},"headers":[],"relativePath":"en/players/visits.md","filePath":"en/players/visits.md"}'),s={name:"en/players/visits.md"};function r(n,e,l,d,h,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="visits-and-shops" tabindex="-1">Visits and shops <a class="header-anchor" href="#visits-and-shops" aria-label="Permalink to &quot;Visits and shops&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Choose a visit on the world map, via a caravan or an available action. An ordinary visit loads a copy of another colony, not the host&#39;s current authoritative simulation. Guest pawns remain guests; use the end-visit action to return.</p><p>You cannot simply take arbitrary goods home from the visited copy. Permitted exchange uses the host&#39;s shop and server operations: purchases are wallet-funded and tracked separately from the copied map state.</p><p>For real-time cooperation, choose a live visit and wait for host consent. It is a separate mode with different return and connection behavior.</p><h2 id="visit-flow" tabindex="-1">Ordinary visits and buying from a shelf <a class="header-anchor" href="#visit-flow" aria-label="Permalink to &quot;Ordinary visits and buying from a shelf {#visit-flow}&quot;">​</a></h2><ol><li>At a foreign settlement, choose <strong>Visit</strong> by caravan/pods, not real raid or live.</li><li>Your home is saved. A copy of the host map loads with copies of your pawns; an offline host&#39;s real map does not start running.</li><li>Tour the colony. Goods picked up from the floor do not travel home. Use <strong>Buy</strong> only for items marked <strong>For sale</strong>, paying from the wallet.</li><li><strong>End visit</strong> restores your home map. Purchases arrive there as server parcels.</li></ol><p>To sell at home, select an item → <strong>For sale…</strong>, set a price and save. The shelf publishes with that save. Sold goods are collected from stocks on next login. This differs from a global market lot.</p><h2 id="visit-load" tabindex="-1">If the visited map cannot load <a class="header-anchor" href="#visit-load" aria-label="Permalink to &quot;If the visited map cannot load {#visit-load}&quot;">​</a></h2><p>The host may have a mod or DLC you lack; validation should stop before loading and identify dependencies. Never remove XML objects from a foreign save to force entry. Disabled visits or no host colony require another action, not forced loading.</p><p>On return, check your home map and mailbox. A visit copy must not overwrite home. For real-time interaction request a live visit, which requires an online consenting host and different rules for returning actual guest pawns.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Visits default to a 12-hour limit. Never replace your home save with a visited copy. Blocking messages does not itself prohibit visiting.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: the active map</a></li><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',16)])])}const v=a(s,[["render",r]]);export{m as __pageData,v as default};
